{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "The specific review questions are: (1) Are organisational-level mental health programmes effective in reducing stress, burnout, non-clinical depressive and anxiety symptoms, and in enhancing mental wellbeing in construction workers? (2) Are organisational-level mental health programmes effective in reducing stress, burnout, non-clinical depressive and anxiety symptoms and in enhancing mental wellbeing in SME construction workers?",
      "reason": "The review objectives/questions are explicitly stated as two research questions in the Objectives section, and the abstract also states the review aim."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "Are organisational-level mental health programmes effective in reducing stress, burnout, non-clinical depressive and anxiety symptoms, and in enhancing mental wellbeing in construction workers?",
      "reason": "The questions implicitly cover population (construction workers), intervention (organisational-level mental health programmes), and outcomes (stress, burnout, depressive/anxiety symptoms, wellbeing), but no formal PICO framework or explicit statement of planned comparisons (e.g., intervention vs control) is reported."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Table 1. Inclusion and exclusion criteria. | Population | Construction industry | 1. Workers and managers in the construction industry according to the NACE classification... | Intervention | Organisational-level mental health promotion intervention... | Comparison | Control group Pre- and post-comparison | 7. All experimental study designs with a comparison group, including RCTs, cRCTs, controlled before- and after- designs... | Outcomes | Primary: Mental health and wellbeing | 9. Stress, burnout, non-clinical depression and anxiety symptoms, mental wellbeing measured by validated scales...",
      "reason": "Table 1 and text_13 fully specify eligibility criteria by PICO components: population (construction workers/managers), intervention type, eligible study designs (RCTs, cRCTs, controlled/uncontrolled before-after), and outcomes, with detailed inclusions and exclusions."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "included studies published in English between January 2010 and May 2022 to reflect intervention efforts in the modern construction workplace... Unpublished 'grey literature' was not included.",
      "reason": "Report characteristics are specified: language (English), publication date range (January 2010 to May 2022), peer-reviewed journal publication (text_3), and exclusion of grey literature."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_18",
      "quote": "Primary reasons for exclusion at full-text review were ineligible outcomes (n = 14) and ineligible study design (n = 10).",
      "reason": "Exclusion for 'ineligible outcomes' is reported but the review does not distinguish between studies where outcomes were not measured versus outcomes measured but results not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": "text_3",
      "quote": "Quality appraisal was conducted using the QATQS scale, a narrative synthesis was applied.",
      "reason": "A narrative synthesis is mentioned, but no groups used in the synthesis are specified or linked to the review objectives/comparisons; no subgrouping or synthesis grouping scheme is reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "In a staged approach only studies with a control group and with a before- and at least one after measurement post intervention were deemed eligible in the first round of selection as they provide the most robust evidence.",
      "reason": "Rationales are given for some restrictions (staged design approach for robust evidence; date range 'to reflect intervention efforts in the modern construction workplace' in text_12), but no rationale is provided for other restrictions such as the English-language limit or exclusion of grey literature."
    }
  ],
  "confidence": 88
}

